import {validateProvenance,calibrationIssues} from './provenance.js';
import {MBSE_TYPES,MBSE_RELATIONS,DIAGRAMS,normalizeEngineering,validateEngineering,expandedNeeds} from './mbse.js';
export const TYPES={...MBSE_TYPES,factory:'Fabrică',area:'Hală / zonă',line:'Linie',cell:'Celulă',assembly:'Ansamblu',subassembly:'Subansamblu',source:'Sursă / comenzi',operation:'Operație',inspection:'Inspecție / test',transport:'Transport',sink:'Produs final',machine:'Mașină',robot:'Robot',tool:'Dispozitiv / sculă',hardware:'Hardware / PLC',sensor:'Senzor',software:'Software / serviciu',person:'Operator',team:'Echipă',utility:'Utilitate',material:'Material / componentă',requirement:'Cerință',function:'Funcție',mission:'Misiune',hazard:'Hazard',custom:'Element personalizat'};
export const PROCESS=['operation','inspection','transport'];export const POOLS=['machine','robot','tool','hardware','sensor','software','person','team','utility'];
export const RELATIONS={...MBSE_RELATIONS,flow:'Flux de produs',requires:'Necesită resursă',consumes:'Consumă material',produces:'Produce componentă în stoc',contains:'Conține',allocated:'Alocare funcțională',data:'Flux de date',controls:'Controlează',satisfies:'Satisface cerința',mitigates:'Reduce hazardul',depends:'Depinde de'};
export const FIELDS={interval:['Interval sosiri','s',1,86400,60],limit:['Număr maxim sosiri (0 = nelimitat)','buc',0,1000000,0],cycle:['Timp procesare','s',.01,86400,60],capacity:['Capacitate paralelă','buc',1,1000,1],buffer:['Buffer intrare','buc',1,100000,10],variation:['Variație uniformă ±','ratio',0,.9,0],setup:['Setup per piesă','s',0,86400,0],scrap:['Probabilitate rebut','ratio',0,1,0],power:['Putere în procesare','kW',0,100000,0],cost:['Cost pe oră ocupată','EUR/h',0,100000,0],mtbf:['Timp mediu de funcționare până la defectare (0 = fără)','s',0,100000000,0],mttr:['Durată medie reparație','s',0,86400,0],on:['Durată disponibilă (0 = mereu)','s',0,604800,0],off:['Durată indisponibilă','s',0,604800,0],speed:['Factor viteză (durata ÷ factor)','ratio',.01,100,1],latency:['Latență per utilizare','s',0,86400,0],stock:['Stoc inițial','buc',0,10000000,1000],unitCost:['Cost material','EUR/buc',0,1000000,0]};
export function fields(type){if(type==='source')return ['interval','limit'];if(PROCESS.includes(type))return ['cycle','capacity','buffer','variation','setup','scrap','power','cost','mtbf','mttr','on','off'];if(POOLS.includes(type))return ['capacity','on','off','speed','latency','cost'];if(type==='material')return ['stock','unitCost'];return []}
export function uid(prefix='id'){return prefix+'-'+globalThis.crypto.randomUUID().slice(0,8)}
export function node(type,name,id=uid(type)){return{id,type,name,description:'',parent:'',params:Object.fromEntries(fields(type).map(k=>[k,FIELDS[k][4]])),bindings:{},attributes:[],stereotypes:[],ports:[],properties:[],behavior:'',moflt:''}}
export function emptyModel(){return{version:2,library:[],name:'Fabrica mea',nodes:[],edges:[],variables:[],diagrams:[{id:'main',name:'Flux de producție',kind:'process',items:[]}],settings:{hours:8,seed:42,replications:1}}}
export function effective(model,n){const p={...n.params};for(const[k,id]of Object.entries(n.bindings||{})){const v=model.variables.find(v=>v.id===id);if(!v)throw Error('Variabilă lipsă: '+id);p[k]=v.value}return p}
export function migrate(old){if(old.version===2)return normalizeEngineering(structuredClone(old));if(old.version!==1||!Array.isArray(old.lines))throw Error('Versiune de model necunoscută.');const m=emptyModel();m.name=old.name;let y=100;for(const l of old.lines){const group=node('line',l.name,l.id);m.nodes.push(group);let prev=node('source','Comenzi · '+l.name,l.id+'-source');prev.params.interval=l.arrival;prev.parent=l.id;m.nodes.push(prev);let x=50;m.diagrams[0].items.push({nodeId:prev.id,x,y});for(const s of l.stations){const n=node('operation',s.name,s.id);Object.assign(n.params,{cycle:s.cycle,capacity:s.capacity,buffer:s.buffer,variation:s.variation});n.parent=l.id;m.nodes.push(n);m.edges.push({id:uid('edge'),type:'flow',from:prev.id,to:n.id,weight:1,delay:0,quantity:1});x+=230;m.diagrams[0].items.push({nodeId:n.id,x,y});prev=n}const sink=node('sink','Produse · '+l.name,l.id+'-sink');sink.parent=l.id;m.nodes.push(sink);m.edges.push({id:uid('edge'),type:'flow',from:prev.id,to:sink.id,weight:1,delay:0,quantity:1});m.diagrams[0].items.push({nodeId:sink.id,x:x+230,y});y+=230}
 for(const e of old.elements||[])m.nodes.push({...node(({M:'mission',O:'function',F:'function',L:'assembly',T:'hardware'})[e.level],e.name,e.id),description:'Nivel MOFLT '+e.level});for(const r of old.requirements||[]){m.nodes.push(node('requirement',r.text,r.id));for(const t of r.targets)m.edges.push({id:uid('edge'),type:'satisfies',from:t,to:r.id,quantity:1,weight:1,delay:0})}for(const e of old.links||[])m.edges.push({id:uid('edge'),type:'allocated',from:e.from,to:e.to,quantity:1,weight:1,delay:0});for(const h of old.hazards||[])m.nodes.push({...node('hazard',h.text,h.id),description:h.mitigation+' | '+h.status});return m}
export function validateModel(m,{simulation=false}={}){
 if(m?.version!==2||typeof m.name!=='string')throw Error('Model version=2 necesar.');for(const k of ['nodes','edges','variables','diagrams'])if(!Array.isArray(m[k]))throw Error('Colecție lipsă: '+k);if(m.nodes.length>500||m.edges.length>2000||m.variables.length>1000||m.diagrams.length>50)throw Error('Limita modelului: 500 elemente, 2000 relații, 1000 variabile, 50 diagrame.');
 if(!m.diagrams.length)throw Error('Păstrează cel puțin o diagramă.');
 for(const n of m.nodes)if(!n.params||typeof n.params!=='object'||!n.bindings||typeof n.bindings!=='object'||Array.isArray(n.bindings))throw Error('Parametri sau legături de variabile invalide.');
 const ids=new Set();const checkId=id=>{if(typeof id!=='string'||!id||ids.has(id))throw Error('ID lipsă sau duplicat: '+id);ids.add(id)};for(const v of m.variables){checkId(v.id);if(typeof v.name!=='string'||!Number.isFinite(v.value)||typeof v.unit!=='string')throw Error('Variabilă invalidă.');}
 for(const n of m.nodes){checkId(n.id);if(!Object.hasOwn(TYPES,n.type)||typeof n.name!=='string'||!n.name.trim()||typeof n.description!=='string'||!Array.isArray(n.attributes))throw Error('Element invalid.');for(const a of n.attributes)if(typeof a.name!=='string'||typeof a.value!=='string'||typeof a.unit!=='string')throw Error('Atribut invalid.');const p=effective(m,n);for(const k of fields(n.type)){const f=FIELDS[k];if(!Number.isFinite(p[k])||p[k]<f[2]||p[k]>f[3]||(['capacity','buffer','limit'].includes(k)&&!Number.isInteger(p[k])))throw Error(`${n.name}: ${f[0]} invalid.`)}for(const[k,v]of Object.entries(n.bindings||{})){if(!fields(n.type).includes(k)||m.variables.find(x=>x.id===v)?.unit!==FIELDS[k][1])throw Error(n.name+': unitate incompatibilă pentru '+k)}if(PROCESS.includes(n.type)&&p.capacity>100)throw Error('Maximum 100 canale per operație.');}
 const byId=new Map(m.nodes.map(n=>[n.id,n]));for(const n of m.nodes){let parent=n.parent;const seen=new Set([n.id]);while(parent){if(seen.has(parent)||!byId.has(parent))throw Error('Ierarhie circulară sau părinte lipsă.');seen.add(parent);parent=byId.get(parent).parent}}
 for(const e of m.edges){checkId(e.id);const a=byId.get(e.from),b=byId.get(e.to);if(!a||!b||!Object.hasOwn(RELATIONS,e.type))throw Error('Relație invalidă.');if(e.type==='flow'){if(!['source',...PROCESS].includes(a.type)||![...PROCESS,'sink'].includes(b.type))throw Error('Flux: sursă/operație → operație/ieșire.');if(!Number.isFinite(e.weight)||e.weight<=0||!Number.isFinite(e.delay)||e.delay<0||e.delay>86400)throw Error('Pondere sau timp transport invalid.');}if(['requires','consumes'].includes(e.type)){if(!PROCESS.includes(a.type)||(e.type==='requires'?!POOLS.includes(b.type):b.type!=='material')||!Number.isInteger(e.quantity)||e.quantity<1)throw Error('Alocare invalidă: operație → resursă/material, cantitate întreagă pozitivă.');}}
 for(const d of m.diagrams){checkId(d.id);if(typeof d.name!=='string'||!Object.hasOwn(DIAGRAMS,d.kind)||!Array.isArray(d.items))throw Error('Diagramă invalidă.');const seen=new Set();for(const i of d.items){if(!byId.has(i.nodeId)||seen.has(i.nodeId)||!Number.isFinite(i.x)||!Number.isFinite(i.y)||Math.abs(i.x)>20000||Math.abs(i.y)>20000)throw Error('Reprezentare de diagramă invalidă.');seen.add(i.nodeId)}}
 if(!m.settings||!Number.isFinite(m.settings.hours)||m.settings.hours<.01||m.settings.hours>168||!Number.isInteger(m.settings.seed)||m.settings.seed<0||m.settings.seed>2147483647||!Number.isInteger(m.settings.replications)||m.settings.replications<1||m.settings.replications>20)throw Error('Setări simulare invalide.');
 validateEngineering(m);validateProvenance(m);
 const warnings=[];if(simulation){if(!m.nodes.some(n=>n.type==='source')||!m.nodes.some(n=>n.type==='sink'))throw Error('Adaugă cel puțin o sursă și o ieșire.');for(const n of m.nodes.filter(n=>['source',...PROCESS].includes(n.type)))if(!m.edges.some(e=>e.type==='flow'&&e.from===n.id))throw Error(n.name+': flux de ieșire lipsă.');const reaches=new Set(m.nodes.filter(n=>n.type==='sink').map(n=>n.id));let changed=true;while(changed){changed=false;for(const e of m.edges.filter(e=>e.type==='flow'))if(reaches.has(e.to)&&!reaches.has(e.from)){reaches.add(e.from);changed=true}}for(const n of m.nodes.filter(n=>['source',...PROCESS].includes(n.type)))if(!reaches.has(n.id))throw Error(n.name+': nu există cale spre produs final.');for(const n of m.nodes.filter(n=>POOLS.includes(n.type)||n.type==='material'))if(!m.edges.some(e=>['requires','consumes','produces','staffedBy'].includes(e.type)&&e.to===n.id))warnings.push(n.name+': descriptiv, fără alocare în calcul.');}
 for(const e of m.edges.filter(e=>e.type==='produces'))if(!PROCESS.includes(byId.get(e.from).type)||byId.get(e.to).type!=='material'||!Number.isInteger(e.quantity)||e.quantity<1)throw Error('Producție de componente: operație → material, cantitate întreagă pozitivă.');
 if(simulation){let wakes=0;for(const n of m.nodes.filter(n=>PROCESS.includes(n.type)||POOLS.includes(n.type))){const p=effective(m,n);if(p.on&&p.off)wakes+=2*Math.ceil(m.settings.hours*3600/(p.on+p.off));const needs=expandedNeeds(m,n);for(const[id,q]of needs)if(q>effective(m,byId.get(id)).capacity)throw Error(n.name+': necesarul depășește capacitatea resursei '+byId.get(id).name)}if(wakes>200000)throw Error('Prea multe schimbări de calendar; mărește perioadele ON/OFF sau redu orizontul.');const reachable=new Set(m.nodes.filter(n=>n.type==='source').map(n=>n.id));let changed=true;while(changed){changed=false;for(const e of m.edges.filter(e=>e.type==='flow'))if(reachable.has(e.from)&&!reachable.has(e.to)){reachable.add(e.to);changed=true}}for(const n of m.nodes.filter(n=>PROCESS.includes(n.type)))if(!reachable.has(n.id))warnings.push(n.name+': operație fără alimentare din surse.');}
 if(simulation){const missing=calibrationIssues(m).length;if(missing)warnings.push(missing+' parametri necesită calibrare; rezultat exploratoriu.');}
 return warnings;
}
export function example(){const m=emptyModel();m.name='Fabrica integrată · Actuatoare';const add=(id,type,name,x,y)=>{const n=node(type,name,id);m.nodes.push(n);if(x!=null)m.diagrams[0].items.push({nodeId:id,x,y});return n};add('factory','factory','Fabrica Orăștie');add('line','line','Linie actuatoare').parent='factory';add('assembly','assembly','Actuator');add('sub','subassembly','Modul electronic').parent='assembly';add('src','source','Comenzi',40,160).params.interval=50;add('prep','operation','Pregătire kit',290,160).params.cycle=35;add('build','operation','Asamblare',540,160).params.cycle=65;add('test','inspection','Test funcțional',790,160).params.cycle=85;add('out','sink','Produse conforme',1040,160);add('team','team','Tehnicieni',430,400).params.capacity=2;const plc=add('plc','hardware','Banc + PLC',750,400);plc.params.capacity=1;const sw=add('sw','software','Software test',1000,400);sw.params.latency=4;const mat=add('parts','material','Kit componente',180,400);mat.params.stock=1000;mat.params.unitCost=18;const edge=(type,from,to,extra={})=>m.edges.push({id:uid('rel'),type,from,to,weight:1,quantity:1,delay:0,...extra});edge('flow','src','prep');edge('flow','prep','build',{delay:3});edge('flow','build','test');edge('flow','test','out',{weight:95});edge('flow','test','build',{weight:5});edge('requires','prep','team');edge('requires','build','team');edge('requires','test','plc');edge('requires','test','sw');edge('consumes','prep','parts');edge('allocated','sub','plc');for(const n of m.nodes.filter(n=>['source',...PROCESS,'sink'].includes(n.type)))n.parent='line';m.variables.push({id:'test-cycle',name:'Durată test',value:85,unit:'s'});m.nodes.find(n=>n.id==='test').bindings.cycle='test-cycle';m.diagrams.push({id:'structure',name:'Descompunere produs & fabrică',kind:'structure',items:m.nodes.map((n,i)=>({nodeId:n.id,x:40+i%4*250,y:70+Math.floor(i/4)*170}))});return m}
